//#region src/paradigms/rsi-reversion.ts
const rsiReversionStrategy = {
	id: "rsi-reversion",
	horizon: "short",
	name: "RSI 短线极值回归",
	summary: "短周期 RSI(2) 进入极端超卖区抄底，快速反弹后止盈（经典均值回归）",
	params: [
		{
			key: "rsiPeriod",
			label: "RSI 周期",
			default: 2,
			min: 2,
			max: 14,
			step: 1
		},
		{
			key: "entryThreshold",
			label: "入场超卖阈值",
			default: 10,
			min: 1,
			max: 30,
			step: 1
		},
		{
			key: "exitThreshold",
			label: "出场止盈阈值",
			default: 60,
			min: 50,
			max: 95,
			step: 1
		}
	],
	compute(bars, params) {
		const period = Math.max(2, Math.round(params.rsiPeriod ?? 2));
		const enterThresh = Number(params.entryThreshold ?? 10);
		const exitThresh = Number(params.exitThreshold ?? 60);
		const rsiOf = (values, period) => {
			const out = new Array(values.length).fill(void 0);
			if (!Number.isFinite(period) || period < 1 || values.length < period) return out;
			let gain = 0;
			let loss = 0;
			for (let index = 1; index <= period; index++) {
				const delta = values[index] - values[index - 1];
				if (delta >= 0) gain += delta;
				else loss -= delta;
			}
			gain /= period;
			loss /= period;
			out[period] = loss === 0 ? 100 : 100 - 100 / (1 + gain / loss);
			for (let index = period + 1; index < values.length; index++) {
				const delta = values[index] - values[index - 1];
				gain = (gain * (period - 1) + Math.max(delta, 0)) / period;
				loss = (loss * (period - 1) + Math.max(-delta, 0)) / period;
				out[index] = loss === 0 ? 100 : 100 - 100 / (1 + gain / loss);
			}
			return out;
		};
		const rsiValues = rsiOf(bars.map((b) => b.close), period);
		const signals = [];
		let inPosition = false;
		for (let i = 0; i < bars.length; i++) {
			const val = rsiValues[i];
			if (val === void 0 || Number.isNaN(val)) continue;
			if (!inPosition && val < enterThresh) {
				signals.push({
					index: i,
					time: bars[i].openTime,
					action: "entry",
					direction: "long",
					price: bars[i].close,
					reason: `RSI(${period}) 达到极端超卖值 (${val.toFixed(1)} < ${enterThresh})，触发反弹买入`,
					reasonKey: "strat.rsi-reversion.reason.entry",
					reasonParams: {
						period,
						val: val.toFixed(1),
						thresh: enterThresh
					}
				});
				inPosition = true;
			} else if (inPosition && val > exitThresh) {
				signals.push({
					index: i,
					time: bars[i].openTime,
					action: "exit",
					direction: "flat",
					price: bars[i].close,
					reason: `RSI(${period}) 回升至目标位 (${val.toFixed(1)} > ${exitThresh})，止盈离场`,
					reasonKey: "strat.rsi-reversion.reason.exit",
					reasonParams: {
						period,
						val: val.toFixed(1),
						thresh: exitThresh
					}
				});
				inPosition = false;
			}
		}
		return signals;
	}
};
//#endregion
export { rsiReversionStrategy };
