//#region src/paradigms/ema-crossover.ts
const emaCrossoverStrategy = {
	id: "ema-crossover",
	horizon: "swing",
	name: "EMA 双均线趋势跟踪",
	summary: "快线 EMA 上穿慢线 EMA 金叉做多，死叉平仓（经典中线波段趋势策略）",
	params: [{
		key: "fastPeriod",
		label: "快线周期 (Fast)",
		default: 20,
		min: 5,
		max: 50,
		step: 1
	}, {
		key: "slowPeriod",
		label: "慢线周期 (Slow)",
		default: 60,
		min: 20,
		max: 200,
		step: 1
	}],
	compute(bars, params) {
		const fastP = Math.max(2, Math.round(params.fastPeriod ?? 20));
		const slowP = Math.max(fastP + 1, Math.round(params.slowPeriod ?? 60));
		const fmtPrice = (value) => {
			if (!Number.isFinite(value)) return "—";
			const abs = Math.abs(value);
			if (abs < 1) return value.toFixed(abs >= .01 ? 4 : 6);
			return value.toFixed(Math.abs(Number(value.toFixed(2)) - value) < 1e-9 ? 2 : 3);
		};
		const emaOf = (values, period) => {
			const out = new Array(values.length).fill(void 0);
			if (!Number.isFinite(period) || period < 1 || values.length < period) return out;
			const k = 2 / (period + 1);
			let seed = 0;
			for (let index = 0; index < period; index++) seed += values[index];
			let prev = seed / period;
			out[period - 1] = prev;
			for (let index = period; index < values.length; index++) {
				prev = values[index] * k + prev * (1 - k);
				out[index] = prev;
			}
			return out;
		};
		const closes = bars.map((b) => b.close);
		const fastEma = emaOf(closes, fastP);
		const slowEma = emaOf(closes, slowP);
		const signals = [];
		let inPosition = false;
		for (let i = 1; i < bars.length; i++) {
			const prevFast = fastEma[i - 1];
			const prevSlow = slowEma[i - 1];
			const currFast = fastEma[i];
			const currSlow = slowEma[i];
			if (prevFast === void 0 || prevSlow === void 0 || currFast === void 0 || currSlow === void 0) continue;
			if (!inPosition && prevFast <= prevSlow && currFast > currSlow) {
				signals.push({
					index: i,
					time: bars[i].openTime,
					action: "entry",
					direction: "long",
					price: bars[i].close,
					reason: `EMA(${fastP}) (${fmtPrice(currFast)}) 上穿 EMA(${slowP}) (${fmtPrice(currSlow)}) 形成金叉`,
					reasonKey: "strat.ema-crossover.reason.entry",
					reasonParams: {
						fastP,
						fast: fmtPrice(currFast),
						slowP,
						slow: fmtPrice(currSlow)
					}
				});
				inPosition = true;
			} else if (inPosition && prevFast >= prevSlow && currFast < currSlow) {
				signals.push({
					index: i,
					time: bars[i].openTime,
					action: "exit",
					direction: "flat",
					price: bars[i].close,
					reason: `EMA(${fastP}) (${fmtPrice(currFast)}) 下穿 EMA(${slowP}) (${fmtPrice(currSlow)}) 形成死叉`,
					reasonKey: "strat.ema-crossover.reason.exit",
					reasonParams: {
						fastP,
						fast: fmtPrice(currFast),
						slowP,
						slow: fmtPrice(currSlow)
					}
				});
				inPosition = false;
			}
		}
		return signals;
	}
};
//#endregion
export { emaCrossoverStrategy };
