//#region src/instrument-form.ts
/** 永续规范形后缀（规范词汇的唯一载体，见 docs/guides/symbol-vocabulary.md）。 */
const SWAP_SYMBOL_SUFFIX = "-SWAP";
/**
* 由规范符号裁决形态：带 `-SWAP` 后缀为 `perp`，否则 `spot`。
* 输入容忍小写与空白（trim + 大写化）后判定，**不剥后缀**——剥了就不是同一个符号了。
*/
function instrumentFormOf(symbol) {
	return symbol.trim().toUpperCase().endsWith("-SWAP") ? "perp" : "spot";
}
//#endregion
export { SWAP_SYMBOL_SUFFIX, instrumentFormOf };
