//#region src/paradigms/momentum-12m.ts
const momentum12mStrategy = {
	id: "momentum-12m",
	horizon: "long",
	name: "12 个月动量择时",
	summary: "近 12 个月动量为正且站上年线做多，动量转负或破位离场（低换手长线动量）",
	params: [{
		key: "lookbackBars",
		label: "动量回溯周期 (K线)",
		default: 250,
		min: 50,
		max: 500,
		step: 10
	}],
	compute(bars, params) {
		const lookback = Math.max(10, Math.round(params.lookbackBars ?? 250));
		const fmtPrice = (value) => {
			if (!Number.isFinite(value)) return "—";
			const abs = Math.abs(value);
			if (abs < 1) return value.toFixed(abs >= .01 ? 4 : 6);
			return value.toFixed(Math.abs(Number(value.toFixed(2)) - value) < 1e-9 ? 2 : 3);
		};
		const smaOf = (values, period) => {
			const out = new Array(values.length).fill(void 0);
			if (!Number.isFinite(period) || period < 1 || values.length < period) return out;
			let sum = 0;
			for (let index = 0; index < values.length; index++) {
				sum += values[index];
				if (index >= period) sum -= values[index - period];
				if (index >= period - 1) out[index] = sum / period;
			}
			return out;
		};
		const smaValues = smaOf(bars.map((b) => b.close), lookback);
		const signals = [];
		let inPosition = false;
		for (let i = lookback; i < bars.length; i++) {
			const currentClose = bars[i].close;
			const pastClose = bars[i - lookback].close;
			const currentSma = smaValues[i];
			if (pastClose <= 0 || currentSma === void 0) continue;
			const momentumReturn = (currentClose - pastClose) / pastClose;
			if (!inPosition && momentumReturn > 0 && currentClose > currentSma) {
				signals.push({
					index: i,
					time: bars[i].openTime,
					action: "entry",
					direction: "long",
					price: currentClose,
					reason: `近 ${lookback} 周期动量为正 (+${(momentumReturn * 100).toFixed(1)}%) 且位于均线 (${fmtPrice(currentSma)}) 之上，确认强动量`,
					reasonKey: "strat.momentum-12m.reason.entry",
					reasonParams: {
						n: lookback,
						pct: (momentumReturn * 100).toFixed(1),
						sma: fmtPrice(currentSma)
					}
				});
				inPosition = true;
			} else if (inPosition && (momentumReturn <= 0 || currentClose < currentSma)) {
				const exitCause = momentumReturn <= 0 ? "动量转为负值" : "跌破基准均线";
				signals.push({
					index: i,
					time: bars[i].openTime,
					action: "exit",
					direction: "flat",
					price: currentClose,
					reason: `${exitCause} (${(momentumReturn * 100).toFixed(1)}% / SMA ${fmtPrice(currentSma)})，动量衰减平仓`,
					reasonKey: "strat.momentum-12m.reason.exit",
					reasonParams: {
						cause: momentumReturn <= 0 ? "momentumNegative" : "belowBaseline",
						pct: (momentumReturn * 100).toFixed(1),
						sma: fmtPrice(currentSma)
					}
				});
				inPosition = false;
			}
		}
		return signals;
	}
};
//#endregion
export { momentum12mStrategy };
