//#region src/paradigms/bollinger-reversion.ts
const bollingerReversionStrategy = {
	id: "bollinger-reversion",
	horizon: "swing",
	name: "布林带下轨均值回归",
	summary: "价格跌破布林线下轨时介入抄底，反弹至中轨（基准均线）时平仓（波段通道回归）",
	params: [{
		key: "period",
		label: "布林周期",
		default: 20,
		min: 5,
		max: 50,
		step: 1
	}, {
		key: "multiplier",
		label: "标准差倍数 (k)",
		default: 2,
		min: 1,
		max: 4,
		step: .5
	}],
	compute(bars, params) {
		const period = Math.max(5, Math.round(params.period ?? 20));
		const k = Number(params.multiplier ?? 2);
		const fmtPrice = (value) => {
			if (!Number.isFinite(value)) return "—";
			const abs = Math.abs(value);
			if (abs < 1) return value.toFixed(abs >= .01 ? 4 : 6);
			return value.toFixed(Math.abs(Number(value.toFixed(2)) - value) < 1e-9 ? 2 : 3);
		};
		const smaOf = (values, period) => {
			const out = new Array(values.length).fill(void 0);
			if (!Number.isFinite(period) || period < 1 || values.length < period) return out;
			let sum = 0;
			for (let index = 0; index < values.length; index++) {
				sum += values[index];
				if (index >= period) sum -= values[index - period];
				if (index >= period - 1) out[index] = sum / period;
			}
			return out;
		};
		const stdevOf = (values, period) => {
			const out = new Array(values.length).fill(void 0);
			if (!Number.isFinite(period) || period < 1 || values.length < period) return out;
			for (let index = period - 1; index < values.length; index++) {
				let mean = 0;
				for (let offset = 0; offset < period; offset++) mean += values[index - offset];
				mean /= period;
				let variance = 0;
				for (let offset = 0; offset < period; offset++) {
					const delta = values[index - offset] - mean;
					variance += delta * delta;
				}
				out[index] = Math.sqrt(variance / period);
			}
			return out;
		};
		const closes = bars.map((b) => b.close);
		const mid = smaOf(closes, period);
		const sd = stdevOf(closes, period);
		const lower = closes.map((_, index) => {
			const base = mid[index];
			const dev = sd[index];
			return base === void 0 || dev === void 0 ? void 0 : base - k * dev;
		});
		const signals = [];
		let inPosition = false;
		for (let i = period - 1; i < bars.length; i++) {
			const currentClose = bars[i].close;
			const currentLower = lower[i];
			const currentMid = mid[i];
			if (currentLower === void 0 || currentMid === void 0) continue;
			if (!inPosition && currentClose < currentLower) {
				signals.push({
					index: i,
					time: bars[i].openTime,
					action: "entry",
					direction: "long",
					price: currentClose,
					reason: `收盘价 (${fmtPrice(currentClose)}) 跌破布林下轨 (${fmtPrice(currentLower)})，触发波段均值回归`,
					reasonKey: "strat.bollinger-reversion.reason.entry",
					reasonParams: {
						close: fmtPrice(currentClose),
						band: fmtPrice(currentLower)
					}
				});
				inPosition = true;
			} else if (inPosition && currentClose >= currentMid) {
				signals.push({
					index: i,
					time: bars[i].openTime,
					action: "exit",
					direction: "flat",
					price: currentClose,
					reason: `收盘价 (${fmtPrice(currentClose)}) 成功回归至布林中轨 (${fmtPrice(currentMid)})，完成目标止盈`,
					reasonKey: "strat.bollinger-reversion.reason.exit",
					reasonParams: {
						close: fmtPrice(currentClose),
						mid: fmtPrice(currentMid)
					}
				});
				inPosition = false;
			}
		}
		return signals;
	}
};
//#endregion
export { bollingerReversionStrategy };
