//#region src/paradigms/sma-baseline.ts
const smaBaselineStrategy = {
	id: "sma-baseline",
	horizon: "long",
	name: "200 日均线牛熊择时基线",
	summary: "收盘价站上 SMA200 均线做多，跌破均线空仓避险（长线资产配置经典基线）",
	params: [{
		key: "period",
		label: "长期均线周期",
		default: 200,
		min: 50,
		max: 300,
		step: 10
	}],
	compute(bars, params) {
		const period = Math.max(10, Math.round(params.period ?? 200));
		const fmtPrice = (value) => {
			if (!Number.isFinite(value)) return "—";
			const abs = Math.abs(value);
			if (abs < 1) return value.toFixed(abs >= .01 ? 4 : 6);
			return value.toFixed(Math.abs(Number(value.toFixed(2)) - value) < 1e-9 ? 2 : 3);
		};
		const smaOf = (values, period) => {
			const out = new Array(values.length).fill(void 0);
			if (!Number.isFinite(period) || period < 1 || values.length < period) return out;
			let sum = 0;
			for (let index = 0; index < values.length; index++) {
				sum += values[index];
				if (index >= period) sum -= values[index - period];
				if (index >= period - 1) out[index] = sum / period;
			}
			return out;
		};
		const smaValues = smaOf(bars.map((b) => b.close), period);
		const signals = [];
		let inPosition = false;
		for (let i = period - 1; i < bars.length; i++) {
			const currentClose = bars[i].close;
			const currentSma = smaValues[i];
			if (currentSma === void 0) continue;
			if (!inPosition && currentClose > currentSma) {
				signals.push({
					index: i,
					time: bars[i].openTime,
					action: "entry",
					direction: "long",
					price: currentClose,
					reason: `收盘价 (${fmtPrice(currentClose)}) 站上长期基线 SMA(${period}) (${fmtPrice(currentSma)})，确立多头趋势`,
					reasonKey: "strat.sma-baseline.reason.entry",
					reasonParams: {
						close: fmtPrice(currentClose),
						period,
						sma: fmtPrice(currentSma)
					}
				});
				inPosition = true;
			} else if (inPosition && currentClose < currentSma) {
				signals.push({
					index: i,
					time: bars[i].openTime,
					action: "exit",
					direction: "flat",
					price: currentClose,
					reason: `收盘价 (${fmtPrice(currentClose)}) 跌破长期基线 SMA(${period}) (${fmtPrice(currentSma)})，转入防御避险`,
					reasonKey: "strat.sma-baseline.reason.exit",
					reasonParams: {
						close: fmtPrice(currentClose),
						period,
						sma: fmtPrice(currentSma)
					}
				});
				inPosition = false;
			}
		}
		return signals;
	}
};
//#endregion
export { smaBaselineStrategy };
